import inspect
from matplotlib._api import classproperty

def deprecated(since, *, message='', name='', alternative='', pending=False, obj_type=None, addendum='', removal=''):

    def deprecate(obj, message=message, name=name, alternative=alternative, pending=pending, obj_type=obj_type, addendum=addendum):
        from matplotlib._api import classproperty
        if isinstance(obj, type):
            if obj_type is None:
                obj_type = 'class'
            func = obj.__init__
            name = name or obj.__name__
            old_doc = obj.__doc__

            def finalize(wrapper, new_doc):
                try:
                    obj.__doc__ = new_doc
                except AttributeError:
                    pass
                obj.__init__ = functools.wraps(obj.__init__)(wrapper)
                return obj
        elif isinstance(obj, (property, classproperty)):
            if obj_type is None:
                obj_type = 'attribute'
            func = None
            name = name or obj.fget.__name__
            old_doc = obj.__doc__

            class _deprecated_property(type(obj)):

                def __get__(self, instance, owner=None):
                    if instance is not None or (owner is not None and isinstance(self, classproperty)):
                        emit_warning()
                    return super().__get__(instance, owner)

                def __set__(self, instance, value):
                    if instance is not None:
                        emit_warning()
                    return super().__set__(instance, value)

                def __delete__(self, instance):
                    if instance is not None:
                        emit_warning()
                    return super().__delete__(instance)

                def __set_name__(self, owner, set_name):
                    nonlocal name
                    if name == '<lambda>':
                        name = set_name

            def finalize(_, new_doc):
                return _deprecated_property(fget=obj.fget, fset=obj.fset, fdel=obj.fdel, doc=new_doc)
        else:
            if obj_type is None:
                obj_type = 'function'
            func = obj
            name = name or obj.__name__
            old_doc = func.__doc__

            def finalize(wrapper, new_doc):
                wrapper = functools.wraps(func)(wrapper)
                wrapper.__doc__ = new_doc
                return wrapper

        def emit_warning():
            warn_deprecated(since, message=message, name=name, alternative=alternative, pending=pending, obj_type=obj_type, addendum=addendum, removal=removal)

        def wrapper(*args, **kwargs):
            emit_warning()
            return func(*args, **kwargs)
        old_doc = inspect.cleandoc(old_doc or '').strip('\n')
        notes_header = '\nNotes\n-----'
        second_arg = ' '.join([t.strip() for t in (message, f'Use {alternative} instead.' if alternative else '', addendum) if t])
        new_doc = f'[*Deprecated*] {old_doc}\n{(notes_header if notes_header not in old_doc else '')}\n.. deprecated:: {since}\n   {second_arg}'
        if not old_doc:
            new_doc += '\\ '
        return finalize(wrapper, new_doc)
    return deprecate
